"""Wrap the ES-module builds of three.js and cannon-es as classic global scripts.

The dice page is opened straight from disk as often as it is served, and browsers
refuse to load module scripts from file:// URLs. Inputs are the stock ESM builds
(three r160 `build/three.module.js`, cannon-es `dist/cannon-es.js`); outputs
expose `THREE` and `CANNON` on globalThis. Run from this folder:

    python globalize.py
"""
import re
from pathlib import Path

HERE = Path(__file__).parent

def globalize(source, target, name):
    text = (HERE / source).read_text(encoding='utf-8')
    match = re.search(r'^export \{([^}]*)\};?\s*$', text, re.M)
    assert match, f'{source}: no export list found'
    entries = []
    for item in match.group(1).split(','):
        item = item.strip()
        if not item: continue
        if ' as ' in item:
            local, exported = (part.strip() for part in item.split(' as '))
            entries.append(f'{exported}: {local}')
        else:
            entries.append(item)
    body = text[:match.start()] + text[match.end():]
    assert 'import.meta' not in body and not re.search(r'^import\b', body, re.M), f'{source}: unsupported module syntax'
    out = (f'/* {name} global build, generated by globalize.py from {source}. Do not edit by hand. */\n'
           '(() => {\n"use strict";\n' + body + f'\nglobalThis.{name} = {{ {", ".join(entries)} }};\n}})();\n')
    (HERE / target).write_text(out, encoding='utf-8')
    print(f'{target}: {len(entries)} exports')

globalize('three.module.js', 'three.global.js', 'THREE')
globalize('cannon-es.js', 'cannon-es.global.js', 'CANNON')
